def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    if v2 == 0:
        return None
    value = v1 / v2
    return {
        "value": value,
        "trace": {
            "remaining_securities": v1,
            "securities_to_be_issued": v2,
            "ratio": value,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "ratio"
            }
        }
    }
